const stableNames=['dirt','cobblestone','sandstone','granite','diorite','andesite','spruce_planks'];
function cheapColumn(q){if(![-3,-2,-1,0].every(y=>full(bot.blockAt(q.offset(0,y,0)))))return false;if(!dirs.every(d=>[-2,-1].every(y=>full(bot.blockAt(q.plus(d).offset(0,y,0))))))return false;const hasPick=bot.inventory.items().some(i=>i.name.endsWith('_pickaxe'));return [0,-1,-2].every(y=>{const n=bot.blockAt(q.offset(0,y,0)).name;return ['grass_block','dirt'].includes(n)||(hasPick&&['stone','granite','diorite','andesite','sandstone'].includes(n))||(n==='sand'&&bot.inventory.items().some(i=>stableNames.includes(i.name)))});}
function contactThreat(){const eye=bot.entity.position.offset(0,1.62,0);return foes().find(e=>{if(Math.abs(e.position.y-bot.entity.position.y)>3&&!['skeleton','stray','witch'].includes(e.name))return false;const r=['skeleton','stray','witch'].includes(e.name)?16:e.name==='creeper'?13:10;if(e.position.distanceTo(bot.entity.position)>r)return false;const v=e.position.offset(0,1.2,0).minus(eye);return !bot.world.raycast(eye,v.unit(),v.norm())});}
async function centerDrop(q){for(const axis of['x','z']){const p=bot.entity.position[axis],t=Math.max(q[axis]+.35,Math.min(q[axis]+.65,p));for(let k=0;k<18&&Math.abs(bot.entity.position[axis]-t)>.035;k++){await bot.lookAt(bot.entity.position.offset(axis==='x'?Math.sign(t-bot.entity.position.x)*4:0,1.4,axis==='z'?Math.sign(t-bot.entity.position.z)*4:0),true);bot.setControlState('sneak',true);bot.setControlState('forward',true);await tick(1);bot.clearControlStates();await tick(1)}if(bot.entity.position[axis]<q[axis]+.29||bot.entity.position[axis]>q[axis]+.71)throw Error('DROP_ALIGNMENT')}}
async function immediateBurial(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();for(let k=0;k<12&&!bot.entity.onGround;k++)await tick(1);const q=bot.entity.position.floored().offset(0,-1,0);if(!bot.entity.onGround||!cheapColumn(q))return false;await centerDrop(q);if(!cheapColumn(q))return false;global.P1DownPending={feet:q.offset(0,-2,0),roof:q,at:Date.now()};let steps=0;try{for(let y=0;y>=-2;y--){life();const b=bot.blockAt(q.offset(0,y,0)),pick=bot.inventory.items().find(i=>i.name.endsWith('_pickaxe'));if(pick&&!['dirt','grass_block','sand'].includes(b.name))await bot.equip(pick,'hand');else await bot.unequip('hand');await bot.dig(b,true,'raycast');steps++;for(let k=0;k<35&&(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12);k++)await tick(1);if(!bot.entity.onGround||Math.abs(bot.entity.position.y-q.y-y)>.12)throw Error('BURIAL_SETTLE')}for(let k=0;k<30&&!bot.inventory.items().some(i=>stableNames.includes(i.name));k++)await tick(1);const item=bot.inventory.items().find(i=>stableNames.includes(i.name));if(!item)throw Error('BURIAL_NO_CAP');await bot.equip(item,'hand');const rd=dirs.find(d=>full(bot.blockAt(q.plus(d))));if(!rd)throw Error('BURIAL_NO_ANCHOR');await bot._placeBlockWithOptions(bot.blockAt(q.plus(rd)),rd.scaled(-1),{forceLook:true});await tick(4);if(!shell(q.offset(0,-2,0)))throw Error('BURIAL_HULL');const inside=foes().filter(e=>Math.abs(e.position.x-q.x-.5)<.85&&Math.abs(e.position.z-q.z-.5)<.85&&e.position.y>=q.y-2.5&&e.position.y<q.y);if(inside.length)throw Error('BURIAL_OCCUPIED_'+inside.map(e=>e.name));global.P1Overland=global.P1DownPending;global.P1DownPending=null;console.log('IN_PROGRAM_BURIAL_VERIFIED',reason,bot.entity.position,bot.health);return true;}catch(e){console.log('BURIAL_ERROR',steps,e.message);if(steps===3&&await rescueCap())return true;throw e;}}
function guardedMovement(sprint=false){const hazards=foes();const m=new Movements(bot);m.canDig=false;m.canOpenDoors=false;m.allowSprinting=sprint;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=3;for(const n of['water','lava','fire','soul_fire','magma_block','sweet_berry_bush','powder_snow','cactus','nether_portal'])if(bot.registry.blocksByName[n])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);m.exclusionAreasStep.push(b=>{const p=b.position||new Vec3(b.x,b.y,b.z);let c=0;for(const e of hazards){if(Math.abs(e.position.y-p.y)>3&&!['skeleton','stray','witch'].includes(e.name))continue;const d=e.position.distanceTo(p),r=e.name==='creeper'?11:['skeleton','stray','witch'].includes(e.name)?16:7;if(d<r)c+=(r-d)*20;}return c});bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=500;}
async function guardedWalk(ms=60000,forceAfterMs=null,target={x:148.5,z:2212.5},nightTrial=false){const hp0=bot.health;let hurt=false,buried=false,phase='WALK',flee=false,lastPlan=0,started=Date.now(),last=bot.entity.position.clone(),progress=Date.now();const onHealth=()=>{if(bot.health<hp0-.25)hurt=true};bot.on('health',onHealth);try{guardedMovement();while(Date.now()-started<ms){life();if(Math.hypot(target.x-bot.entity.position.x,target.z-bot.entity.position.z)<3){phase='TARGET';break}const e=contactThreat(),late=!nightTrial&&bot.time.timeOfDay>=10000,forced=forceAfterMs!==null&&Date.now()-started>=forceAfterMs;const shouldBury=e||hurt||late||forced||Date.now()-started>ms-8000;if(shouldBury){const why=e?'PROXIMITY_'+e.name:hurt?'HURT':late?'BEFORE_NIGHT':forced?'CONTROLLED':'BUDGET';if(await immediateBurial(why)||await surfaceBox(why)){buried=true;phase='BURIED';break}flee=!!e||hurt;}
if(Date.now()-lastPlan>1000||!bot.pathfinder.goal){let tx=target.x,tz=target.z;guardedMovement(flee);if(flee){const es=foes();let dx=0,dz=0;for(const h of es){const d=Math.max(1,h.position.distanceTo(bot.entity.position));dx+=(bot.entity.position.x-h.position.x)/(d*d);dz+=(bot.entity.position.z-h.position.z)/(d*d)}const len=Math.hypot(dx,dz)||1;tx=bot.entity.position.x+dx/len*24;tz=bot.entity.position.z+dz/len*24;}else if(Date.now()-progress>3000){tx=bot.entity.position.x+15;tz=bot.entity.position.z+12;progress=Date.now()}bot.pathfinder.setGoal(new goals.GoalXZ(Math.floor(tx),Math.floor(tz)));lastPlan=Date.now()}
if(bot.entity.position.distanceTo(last)>.7){last=bot.entity.position.clone();progress=Date.now()}if(bot.entity.isInWater){bot.pathfinder.setGoal(null);bot.setControlState('jump',true);await bot.lookAt(bot.entity.position.offset(target.x-bot.entity.position.x,1.4,target.z-bot.entity.position.z),true);bot.setControlState('forward',true)}await tick(1);}if(!buried&&!lost){if(await immediateBurial('FINAL')||await surfaceBox('FINAL')){buried=true;phase='BURIED'}}return{phase,buried,hurt,hp0,hp:bot.health};}finally{bot.removeListener('health',onHealth);bot.pathfinder.setGoal(null);bot.clearControlStates();if(bot.entity.isInWater)bot.setControlState('jump',true);}}

async function surfaceBox(reason){life();bot.pathfinder.setGoal(null);bot.clearControlStates();if(!bot.entity.onGround||bot.entity.isInWater)return false;const p=bot.entity.position.floored(),floor=bot.blockAt(p.offset(0,-1,0));if(!full(floor)||['magma_block','lava'].includes(floor.name))return false;const order=[...dirs];const enemy=foes()[0];if(enemy){const dx=enemy.position.x-p.x,dz=enemy.position.z-p.z;order.sort((a,b)=>(b.x*dx+b.z*dz)-(a.x*dx+a.z*dz))}const missing=[];for(const d of order){for(const y of[-1,0,1]){const q=p.plus(d).offset(0,y,0),b=bot.blockAt(q);if(full(b))continue;if(!['air','cave_air','snow','short_grass','fern','tall_grass'].includes(b.name))return false;missing.push(q)}}const dirt=()=>bot.inventory.items().filter(i=>i.name==='dirt').reduce((a,i)=>a+i.count,0);if(dirt()<missing.length+2)return false;await centerDrop(p);async function put(q,ref,face){if(full(bot.blockAt(q)))return;const it=bot.inventory.items().find(i=>i.name==='dirt');if(!it)throw Error('BOX_NO_DIRT');await bot.equip(it,'hand');await bot._placeBlockWithOptions(bot.blockAt(ref),face,{forceLook:true});await tick(2);if(!full(bot.blockAt(q)))throw Error('BOX_BLOCK_ACK_'+q)}
for(const d of order){await put(p.plus(d).offset(0,-1,0),p.offset(0,-1,0),d);await put(p.plus(d),p.plus(d).offset(0,-1,0),new Vec3(0,1,0));await put(p.plus(d).offset(0,1,0),p.plus(d),new Vec3(0,1,0));}const roof=p.offset(0,2,0);if(!full(bot.blockAt(roof))){let d=order.find(d=>full(bot.blockAt(roof.plus(d))));if(!d){d=order[0];await put(roof.plus(d),p.plus(d).offset(0,1,0),new Vec3(0,1,0));}await put(roof,roof.plus(d),d.scaled(-1));}if(!shell(p))throw Error('BOX_HULL');const inside=foes().filter(e=>Math.abs(e.position.x-p.x-.5)<.85&&Math.abs(e.position.z-p.z-.5)<.85&&e.position.y>=p.y-.5&&e.position.y<p.y+2);if(inside.length)throw Error('BOX_OCCUPIED');global.P1SurfaceBox={feet:p,at:Date.now(),reason};global.P1Overland=null;console.log('SURFACE_BOX_VERIFIED',reason,p,bot.health,dirt());return true;}
async function exitSurfaceBox(target={x:148.5,z:2212.5},allowNight=false){const s=global.P1SurfaceBox;if(!s)return;if(!shell(s.feet)||!s.feet.equals(bot.entity.position.floored()))throw Error('BOX_EXIT_START');if(bot.time.timeOfDay>=10000&&!allowNight)throw Error('BOX_WAIT_DAY');const ds=[...dirs].sort((a,b)=>Math.hypot(target.x-s.feet.x-a.x,target.z-s.feet.z-a.z)-Math.hypot(target.x-s.feet.x-b.x,target.z-s.feet.z-b.z));let chosen=null;for(const d of ds){const door=s.feet.plus(d);if(foes().some(e=>Math.abs(e.position.y-door.y)<4&&e.position.distanceTo(door)<(e.name==='creeper'?8:['skeleton','stray','witch'].includes(e.name)?10:3)))continue;chosen=d;break}if(!chosen)throw Error('BOX_EXIT_THREAT');for(const y of[1,0]){const q=s.feet.plus(chosen).offset(0,y,0);if(bot.blockAt(q).name!=='dirt')throw Error('BOX_EXIT_OWN_KIND');await cut(bot.blockAt(q));}global.P1SurfaceBox=null;console.log('BOX_EXIT_OPEN',s.feet.plus(chosen));}

